def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Identify rectangular patches by color; isolated differently-colored speckles are noise.
    colors=set(v for row in grid for v in row)-{bg}
    for v in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==v]
        if not pts: continue
        r0=min(r for r,c in pts); r1=max(r for r,c in pts)
        c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        area=(r1-r0+1)*(c1-c0+1)
        # Objects of a color can be separated; use local candidate rectangles from components.
        seen=set()
        for p in pts:
            if p in seen: continue
            q=[p]; seen.add(p)
            for r,c in q:
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=r+dr,c+dc
                    if 0<=a<h and 0<=b<w and grid[a][b]==v and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            ys=[r for r,c in q]; xs=[c for r,c in q]
            a0,a1=min(ys),max(ys); b0,b1=min(xs),max(xs)
            ar=(a1-a0+1)*(b1-b0+1)
            if ar>=4 and len(q)/ar>=0.50:
                # Repair nearly solid rectangular object, replacing all interior intrusions.
                for r in range(a0,a1+1):
                    for c in range(b0,b1+1): out[r][c]=v
    # Any non-background color outside repaired solid blocks is a marker/noise pixel.
    solid={(r,c) for r in range(h) for c in range(w) if out[r][c]!=bg}
    # Preserve only contiguous filled rectangular blocks; remove isolated marker colors.
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg and out[r][c]==grid[r][c]:
                v=grid[r][c]
                # pixels not included in a rectangle are noise
                if not any(out[y][x]==v for y in range(max(0,r-1),min(h,r+2)) for x in range(max(0,c-1),min(w,c+2)) if (y,x)!=(r,c)):
                    out[r][c]=bg
    return out

